<script setup lang="ts">
definePageMeta({ layout: 'admin' });
import {settingsService} from '~/modules/settings/service/settings.service';const service=settingsService();const data=ref<any>(null);const pending=ref(false);const error=ref('');const success=ref('');async function load(){const rows=await service.list();data.value=rows[0]||{id:'club',clubName:'GDCSS Castelões',contactEmail:''}}async function save(){pending.value=true;error.value='';try{if(data.value.id)await service.update(data.value.id,data.value);else data.value=await service.create(data.value);success.value='Definições guardadas.';setTimeout(()=>success.value='',2500)}catch(e:any){error.value=e?.data?.message||e.message}finally{pending.value=false}}onMounted(load)</script>
<template><div class="page-stack"><header class="page-heading"><div><p class="eyebrow">Sistema</p><h1>Definições</h1><p class="page-heading__description">Dados gerais da plataforma.</p></div></header><p v-if="success" class="cms-alert cms-alert--success">{{success}}</p><p v-if="error" class="cms-alert cms-alert--danger">{{error}}</p><form v-if="data" class="panel settings-form" style="padding:24px" @submit.prevent="save"><label class="form-field"><span>Nome do clube</span><input v-model="data.clubName" required></label><label class="form-field"><span>Email de contacto</span><input v-model="data.contactEmail" type="email" required></label><div><button class="btn btn--primary" :disabled="pending">{{pending?'A guardar…':'Guardar definições'}}</button></div></form></div></template>
